mapper.select:
SELECT u.id FROM sys_user u WHERE u.status IN (1, 2) AND u.id > #{lastUserId} AND u.id IN
#{id}
ORDER BY u.id LIMIT #{limit}

SELECT DISTINCT up.user_id FROM v_user_post_effective up INNER JOIN sys_user u ON u.id = up.user_id WHERE u.status IN (1, 2) AND up.user_id > #{lastUserId} AND up.post_id IN
#{id}
ORDER BY up.user_id LIMIT #{limit}

SELECT DISTINCT ud.user_id FROM v_user_dept_effective ud INNER JOIN sys_user u ON u.id = ud.user_id WHERE u.status IN (1, 2) AND ud.user_id > #{lastUserId} AND ud.dept_id IN
#{id}
ORDER BY ud.user_id LIMIT #{limit}

SELECT DISTINCT ud.user_id FROM v_user_dept_effective ud INNER JOIN dept_closure dc ON dc.descendant_id = ud.dept_id INNER JOIN sys_user u ON u.id = ud.user_id WHERE u.status IN (1, 2) AND ud.user_id > #{lastUserId} AND dc.ancestor_id IN
#{id}
ORDER BY ud.user_id LIMIT #{limit}
